// Desde enero de 2027 estos indicadores del funnel se homologan con BDC.
// Los titulares del funnel no cambian; solamente cambia su fuente de datos.
const BDC_FUNNEL_START_PERIOD = '2027-01';
const BDC_MANAGED_FUNNEL_FIELDS = new Set(['citasLeadIt','citasFbToro','ventasLeadIt','ventasFb']);

function mergeBdcMetricsIntoFunnel(records = [], bdcRecords = []) {
  const byPeriodBranchApv = new Map();
  for (const periodRecord of bdcRecords || []) {
    if (!periodRecord?.period || periodRecord.period < BDC_FUNNEL_START_PERIOD) continue;
    for (const row of periodRecord.apvs || []) {
      const branch = apvIdentity(row.branch);
      const apv = apvIdentity(row.apv);
      if (!branch || !apv) continue;
      const key = `${periodRecord.period}||${branch}||${apv}`;
      const current = byPeriodBranchApv.get(key) || {
        period:periodRecord.period, sucursal:row.branch, manager:row.manager, vendor:row.apv,
        citasLeadIt:0, citasFbToro:0, ventasLeadIt:0, ventasFb:0,
      };
      current.citasLeadIt += Number(row.efectivosPlanta) || 0;
      current.citasFbToro += Number(row.efectivosPropios) || 0;
      current.ventasLeadIt += Number(row.cierresPlanta) || 0;
      current.ventasFb += Number(row.cierresPropios) || 0;
      current.manager = row.manager || current.manager;
      current.vendor = row.apv || current.vendor;
      byPeriodBranchApv.set(key, current);
    }
  }
  const bdcPeriods = new Set((bdcRecords || []).map(record => record.period).filter(period => period >= BDC_FUNNEL_START_PERIOD));
  const matched = new Set();
  const merged = (records || []).map(record => {
    if (!record?.month || record.month < BDC_FUNNEL_START_PERIOD || !bdcPeriods.has(record.month) || isAdditionalRecord(record)) return record;
    const key = `${record.month}||${apvIdentity(record.sucursal)}||${apvIdentity(record.vendor)}`;
    matched.add(key);
    const bdc = byPeriodBranchApv.get(key) || { citasLeadIt:0, citasFbToro:0, ventasLeadIt:0, ventasFb:0 };
    return { ...record,
      citasLeadIt:bdc.citasLeadIt, citasFbToro:bdc.citasFbToro,
      ventasLeadIt:bdc.ventasLeadIt, ventasFb:bdc.ventasFb, bdcHomologated:true,
    };
  });
  for (const [key, bdc] of byPeriodBranchApv) {
    if (matched.has(key)) continue;
    const base = Object.fromEntries(BASE_FIELDS.map(field => [field.key,0]));
    merged.push({
      id:`bdc-sync-${key}`, ...base,
      sucursal:bdc.sucursal, month:bdc.period, manager:bdc.manager || 'SIN ASIGNAR', vendor:bdc.vendor,
      citasLeadIt:bdc.citasLeadIt, citasFbToro:bdc.citasFbToro,
      ventasLeadIt:bdc.ventasLeadIt, ventasFb:bdc.ventasFb, bdcHomologated:true,
    });
  }
  return merged;
}

function safeDiv(num, den) { if (!den) return 0; return num / den; }

// Estado compartido entre vistas comerciales. BDC conserva filtros propios.
const SHARED_COMMERCIAL_FILTERS = {
  manager: 'todos', vendor: 'todos', branchScope: 'sucursal', periodMode: 'mes', brand: 'todas', branchType: 'NUEVOS',
};
const SHARED_COMMERCIAL_LISTENERS = new Map();
function useSharedCommercialFilter(key) {
  const [value, setLocalValue] = useState(SHARED_COMMERCIAL_FILTERS[key]);
  useEffect(() => {
    if (!SHARED_COMMERCIAL_LISTENERS.has(key)) SHARED_COMMERCIAL_LISTENERS.set(key, new Set());
    const listeners = SHARED_COMMERCIAL_LISTENERS.get(key);
    listeners.add(setLocalValue);
    return () => listeners.delete(setLocalValue);
  }, [key]);
  const setValue = useCallback(next => {
    const resolved = typeof next === 'function' ? next(SHARED_COMMERCIAL_FILTERS[key]) : next;
    SHARED_COMMERCIAL_FILTERS[key] = resolved;
    (SHARED_COMMERCIAL_LISTENERS.get(key) || []).forEach(listener => listener(resolved));
  }, [key]);
  return [value, setValue];
}

// Un APV se identifica por su nombre, ignorando acentos, mayúsculas y espacios.
function apvIdentity(value) {
  return String(value ?? '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]+/g, ' ').trim().replace(/\s+/g, ' ').toUpperCase();
}

function cleanApvName(value) {
  return String(value ?? '').trim().replace(/\s+/g, ' ').toUpperCase();
}

function uniqueApvNames(values = []) {
  const unique = new Map();
  for (const value of values) {
    const key = apvIdentity(value);
    if (key && !unique.has(key)) unique.set(key, cleanApvName(value));
  }
  return Array.from(unique.values());
}

function dedupeApvRecords(rows = []) {
  const unique = new Map();
  for (const row of rows) {
    const identity = apvIdentity(row.vendor);
    if (!identity) continue;
    const key = `${row.sucursal || ''}||${row.month || ''}||${identity}`;
    if (!unique.has(key)) {
      unique.set(key, { ...row, vendor: cleanApvName(row.vendor) });
      continue;
    }
    const current = unique.get(key);
    const merged = { ...current };
    merged.comments = { ...(row.comments || {}), ...(current.comments || {}) };
    if ((!merged.manager || merged.manager === 'SIN ASIGNAR') && row.manager) merged.manager = row.manager;
    for (const field of BASE_FIELDS) {
      merged[field.key] = Math.max(Number(current[field.key]) || 0, Number(row[field.key]) || 0);
    }
    unique.set(key, merged);
  }
  return Array.from(unique.values());
}

// Reasignaciones históricas autorizadas. Se aplican también a futuras
// reimportaciones para que el acumulado mantenga una sola estructura gerencial.
function applyHistoricalManagerMigrations(rows = []) {
  const migrations = [
    { from: 'JUAN LUIS ARIAS', to: 'ALEJANDRO MAYNEZ', effectiveMonth: '2026-02' },
  ];
  return rows.map(row => {
    const migration = migrations.find(item =>
      apvIdentity(row.manager) === apvIdentity(item.from) &&
      String(row.month || '') >= item.effectiveMonth);
    return migration ? { ...row, manager: migration.to } : row;
  });
}

function managerForPeriodReport(manager, periodMode) {
  if (periodMode === 'acumulado' && apvIdentity(manager) === apvIdentity('JUAN LUIS ARIAS')) {
    return 'ALEJANDRO MAYNEZ';
  }
  return manager;
}

const ADDITIONAL_MANAGER = '__ADICIONALES__';
const ADDITIONAL_VENDOR = 'ADICIONALES';
function isAdditionalRecord(record) {
  return record?.manager === ADDITIONAL_MANAGER || record?.vendor === ADDITIONAL_VENDOR;
}

function dedupeApvTeams(teamRows = []) {
  // Primero unir filas de equipo repetidas (misma sucursal y mismo gerente).
  const consolidated = new Map();
  for (const team of teamRows) {
    const key = `${apvIdentity(team.sucursal)}||${apvIdentity(team.manager)}`;
    if (!consolidated.has(key)) {
      consolidated.set(key, { ...team, vendors: [], inactiveVendors: [] });
    }
    const current = consolidated.get(key);
    current.vendors.push(...(team.vendors || []));
    current.inactiveVendors.push(...(team.inactiveVendors || []));
  }
  const consolidatedTeams = Array.from(consolidated.values());
  // Si un APV aparece en dos equipos de la misma sucursal, la asignación más
  // reciente (la última del catálogo) debe ganar. Antes se conservaba la
  // primera y un movimiento podía seguir mostrando al gerente anterior.
  const ownerByBranchApv = new Map();
  for (const team of consolidatedTeams) {
    for (const vendor of uniqueApvNames(team.vendors)) {
      const vendorKey = apvIdentity(vendor);
      if (!vendorKey) continue;
      const inactive = team.inactiveManager || (team.inactiveVendors || [])
        .some(name => apvIdentity(name) === vendorKey);
      const key = `${apvIdentity(team.sucursal)}||${vendorKey}`;
      const previous = ownerByBranchApv.get(key);
      if (!previous || (!inactive && previous.inactive) || inactive === previous.inactive) {
        ownerByBranchApv.set(key, {
          teamKey: `${apvIdentity(team.sucursal)}||${apvIdentity(team.manager)}`,
          inactive,
        });
      }
    }
  }
  return consolidatedTeams.map(team => {
    const currentTeamKey = `${apvIdentity(team.sucursal)}||${apvIdentity(team.manager)}`;
    const branch = apvIdentity(team.sucursal);
    const vendors = uniqueApvNames(team.vendors).filter(vendor => {
      const owner = ownerByBranchApv.get(`${branch}||${apvIdentity(vendor)}`);
      return owner?.teamKey === currentTeamKey;
    });
    // inactiveVendors es una marca de baja; el nombre permanece en vendors para
    // conservar su pertenencia histórica al equipo y permitir reactivarlo.
    const vendorKeys = new Set(vendors.map(apvIdentity));
    const inactiveVendors = uniqueApvNames(team.inactiveVendors)
      .filter(vendor => vendorKeys.has(apvIdentity(vendor)));
    return { ...team, vendors, inactiveVendors };
  });
}

