const KPI_DEFS = [
  { key: 'demosFreshUp', label: 'Demos / Fresh-Up', short: 'Demos', targetKey: 'demosFreshUp', den: 'freshUp', num: 'demos' },
  { key: 'solicitudesFreshUp', label: 'Solicitudes / Fresh-Up', short: 'Solicitudes', targetKey: 'solicitudesFreshUp', den: 'freshUp', num: 'solicitudes' },
  { key: 'avaluosFreshUp', label: 'Avalúos / Fresh-Up', short: 'Avalúos', targetKey: 'avaluosFreshUp', den: 'freshUp', num: 'avaluos' },
  { key: 'tomasAvaluos', label: 'Tomas / Avalúos', short: 'Tomas', targetKey: 'tomasAvaluos', den: 'avaluos', num: 'tomas' },
  { key: 'ventasLeadItPct', label: 'Ventas Lead-it / Lead-it', short: 'V. Lead-it', targetKey: 'ventasLeadIt', den: 'citasLeadIt', num: 'ventasLeadIt' },
  { key: 'ventasFanpagePct', label: 'Ventas Fanpage / Fanpage', short: 'V. Fanpage', targetKey: 'ventasFanpage', den: 'fanpageApv', num: 'ventasFanpageApv' },
  { key: 'ventasFreshUpPct', label: 'Ventas / Fresh-Up', short: 'Ventas', targetKey: 'ventasFreshUp', den: 'freshUp', num: 'ventasTotales' },
  { key: 'entregasFreshUpPct', label: 'Entregas / Fresh-Up', short: 'Entregas', targetKey: 'entregasFreshUp', den: 'freshUp', num: 'entregas' },
];

const SCORE_MAP = { Superado: 5, Cerca: 4, Riesgo: 2, Bajo: 1, 'Muy bajo': 0, 'Sin registro': 0 };

function classifyVsTarget(value, target) {
  if (target === null || target === undefined) return null;
  if (value >= target) return 'Superado';
  if (value >= target * 0.85) return 'Cerca';
  if (value >= target * 0.6) return 'Riesgo';
  if (value >= target * 0.3) return 'Bajo';
  return 'Muy bajo';
}

const SEMAFORO_META = {
  Superado: { color: '#22C55E', bg: '#ECFDF5', label: 'Superado' },
  Cerca: { color: '#16A34A', bg: '#F0FDF4', label: 'Cerca de la meta' },
  Riesgo: { color: '#F59E0B', bg: '#FFFBEB', label: 'En riesgo' },
  Bajo: { color: '#EF4444', bg: '#FEF2F2', label: 'Bajo cumplimiento' },
  'Muy bajo': { color: '#DC2626', bg: '#FEF2F2', label: 'Muy bajo' },
  'Sin registro': { color: '#9CA3AF', bg: '#F9FAFB', label: 'Sin registro' },
};

function computeKpis(rec, targets) {
  const kpis = {};
  let totalScore = 0;
  for (const def of KPI_DEFS) {
    const den = rec[def.den];
    const num = rec[def.num];
    const value = safeDiv(num, den);
    const target = targets[def.targetKey];
    const label = den ? classifyVsTarget(value, target) : 'Sin registro';
    const score = SCORE_MAP[label] ?? 0;
    kpis[def.key] = { value, label, score, target, den, num };
    totalScore += score;
  }
  const maxScore = KPI_DEFS.length * 5;
  let performance, perfColor;
  const pct = totalScore / maxScore;
  if (pct >= 0.8) { performance = 'Excelente Performance'; perfColor = '#16A34A'; }
  else if (pct >= 0.625) { performance = 'Buen Performance'; perfColor = '#22C55E'; }
  else if (pct >= 0.5) { performance = 'Necesita estrategias de mejora'; perfColor = '#F59E0B'; }
  else if (pct >= 0.375) { performance = 'Urge refuerzo de estrategias'; perfColor = '#F97316'; }
  else { performance = 'No funciona para la marca'; perfColor = '#EF4444'; }
  return { kpis, totalScore, maxScore, performance, perfColor };
}

function sumRecords(records) {
  const sums = {};
  for (const f of BASE_FIELDS) sums[f.key] = 0;
  for (const r of records) for (const f of BASE_FIELDS) sums[f.key] += Number(r[f.key]) || 0;
  return sums;
}

// Construye el objeto de "etapas" para el funnel de 14 pasos a partir de un record sumado
function buildStageValues(sums) {
  const v = {};
  for (const st of FUNNEL_STAGES) {
    if (!st.tracked) { v[st.key] = null; continue; }
    if (st.mapFrom) {
      v[st.key] = st.mapFrom.reduce((acc, k) => acc + (sums[k] || 0), 0);
    } else {
      v[st.key] = sums[st.key] ?? 0;
    }
  }
  // Para el funnel principal de 8 pasos, "Total Prospectos" no existe como dato propio:
  // usamos Fresh-Up + Calle + Reactivaciones + Fanpage como proxy de "contactos totales"
  // y lo dejamos explícito en la UI para no inventar precisión que no existe.
  v.contactos = (sums.freshUp || 0) + (sums.calle || 0) + (sums.reactivaciones || 0) + (sums.fanpageApv || 0);
  return v;
}

function fmtPct(v) { if (v === null || v === undefined || !isFinite(v)) return '\u2014'; return (v * 100).toFixed(0) + '%'; }
function fmtPct1(v) { if (v === null || v === undefined || !isFinite(v)) return '\u2014'; return (v * 100).toFixed(1) + '%'; }
function fmtNum(v) { if (v === null || v === undefined) return '\u2014'; return Math.round(v).toLocaleString('es-MX'); }
function fmtSigned(v, suffix='') { const s = v > 0 ? '+' : ''; return `${s}${v}${suffix}`; }

const MONTH_NAMES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
const MONTH_SHORT = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
function monthLabel(ym) { const [y, m] = ym.split('-'); return `${MONTH_NAMES[parseInt(m,10)-1]} ${y}`; }
function monthShort(ym) { const [, m] = ym.split('-'); return MONTH_SHORT[parseInt(m,10)-1]; }

