const USERS_KEY   = 'funnel-kpi-users-v1';
const SESSION_KEY = 'funnel-kpi-session-v1';
const LOCKS_KEY   = 'funnel-kpi-period-locks-v1';
const BDC_KEY     = 'funnel-kpi-bdc-v1';
const INDUSTRY_KEY = 'funnel-kpi-industry-v1';
const AMDA_KEY = 'funnel-kpi-amda-v1';
const GEOINTELLIGENCE_KEY = 'funnel-kpi-geointelligence-v1';
const FULL_BACKUP_KEYS = [
  STORAGE_KEY, TEAMS_KEY, TARGETS_KEY, LOCKS_KEY,
  BDC_KEY, INDUSTRY_KEY, AMDA_KEY, GEOINTELLIGENCE_KEY, BRANCHES_KEY, CUTOFF_KEY,
];

async function exportCompleteBackup() {
  const data = {};
  for (const key of FULL_BACKUP_KEYS) {
    try {
      const result = await window.storage.get(key, true);
      if (result?.value != null) data[key] = result.value;
    } catch (error) {
      console.error(`No se pudo respaldar ${key}`, error);
    }
  }
  const backup = {
    format: 'funnel-kpi-full-backup',
    version: 1,
    exportedAt: new Date().toISOString(),
    keys: data,
  };
  const blob = new Blob([JSON.stringify(backup)], { type: 'application/json;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = `Respaldo_Completo_Funnel_${new Date().toISOString().slice(0,10)}.json`;
  anchor.click();
  URL.revokeObjectURL(url);
}

async function importCompleteBackup(file) {
  const backup = JSON.parse(await file.text());
  if (backup?.format !== 'funnel-kpi-full-backup' || !backup?.keys) {
    throw new Error('El archivo no corresponde a un respaldo completo de Funnel KPI.');
  }
  for (const key of FULL_BACKUP_KEYS) {
    if (backup.keys[key] == null) continue;
    if (key === STORAGE_KEY && typeof window.storage.replaceRecords === 'function') {
      await window.storage.replaceRecords(JSON.parse(backup.keys[key] || '[]'));
    } else {
      await window.storage.set(key, backup.keys[key], true);
    }
  }
}

const DEFAULT_ADMIN = {
  id: 'admin-root',
  username: 'admin',
  password: 'Admin2026!',
  role: 'admin',
  name: 'Administrador',
  sucursal: null,   // acceso a todas
  manager: null,    // sin restricción de equipo
  active: true,
};

// Filtra records según las restricciones del usuario activo
function sessionAllowedBranchNames(session, branchCatalog = DEFAULT_BRANCH_CATALOG) {
  const active = (branchCatalog || []).filter(branch => branch.active !== false);
  if (!session || session.role === 'admin') return active.map(branch => branch.name);
  const brands = Array.isArray(session.brands) && session.brands.length ? new Set(session.brands) : null;
  const branches = Array.isArray(session.branches) && session.branches.length ? new Set(session.branches.map(apvIdentity)) : null;
  const legacyBranch = session.sucursal ? apvIdentity(session.sucursal) : null;
  return active.filter(branch => (!brands || brands.has(branch.brand))
    && (!branches || branches.has(apvIdentity(branch.name)))
    && (!legacyBranch || apvIdentity(branch.name) === legacyBranch)).map(branch => branch.name);
}

function filterBySession(records, session, branchCatalog = DEFAULT_BRANCH_CATALOG) {
  if (!session || session.role === 'admin') return records;
  const allowed = new Set(sessionAllowedBranchNames(session,branchCatalog).map(apvIdentity));
  let out = records.filter(record => allowed.has(apvIdentity(record.sucursal)));
  if (session.role === 'gerente_vtas' && session.manager) out = out.filter(r => r.manager === session.manager);
  return out;
}

function filterBdcBySession(records, session, branchCatalog = DEFAULT_BRANCH_CATALOG) {
  if (!session || session.role === 'admin') return records;
  const allowedNames = sessionAllowedBranchNames(session,branchCatalog);
  const allowed = new Set(allowedNames.map(apvIdentity));
  const activeBranches = (branchCatalog || []).filter(branch=>branch.active!==false);
  const canSeeFullBrand = brand => {
    const catalogBrand = brand === 'CHS' ? 'CHS' : 'CHEVROLET';
    const brandBranches = activeBranches.filter(branch=>branch.brand===catalogBrand).map(branch=>apvIdentity(branch.name));
    return brandBranches.length > 0 && brandBranches.every(branch=>allowed.has(branch));
  };
  return (records || []).map(record => ({
    ...record,
    apvs:(record.apvs||[]).filter(row=>allowed.has(apvIdentity(row.branch))),
    teams:(record.teams||[]).filter(row=>allowed.has(apvIdentity(row.branch))),
    campaigns:(record.campaigns||[]).filter(row=>row.branch==='Fuera del PMA'||allowed.has(apvIdentity(row.branch))),
    sourceRows:(record.sourceRows||[]).filter(row=>canSeeFullBrand(row.brand)),
  }));
}


export default function FunnelKpiApp({ authenticatedSession = null }) {
  const [records, setRecords] = useState(null);
  const [teams, setTeams] = useState(null);
  const [targets, setTargets] = useState(DEFAULT_TARGETS);
  const [loading, setLoading] = useState(true);
  const [view, setView] = useState('dashboard');
  const [sucursal, setSucursal] = useState('Juventud');
  const [selectedMonth, setSelectedMonth] = useState(null);
  const [toast, setToast] = useState(null);
  // La sesión viene directamente de Supabase. Se mantiene la lectura del
  // storage solo como compatibilidad con instalaciones anteriores.
  const [session, setSession] = useState(authenticatedSession);   // usuario logueado
  const [users, setUsers] = useState(null);        // lista de usuarios
  const [periodLocks, setPeriodLocks] = useState([]);
  const [bdcRecords, setBdcRecords] = useState([]);
  const [industryData, setIndustryData] = useState(null);
  const [amdaData, setAmdaData] = useState(null);
  const [geoData, setGeoData] = useState(null);
  const [branchCatalog, setBranchCatalog] = useState(DEFAULT_BRANCH_CATALOG);
  const [cutoffDate, setCutoffDate] = useState('');
  const [globalManager, setGlobalManager] = useSharedCommercialFilter('manager');
  const [globalVendor, setGlobalVendor] = useSharedCommercialFilter('vendor');
  const [globalBranchScope, setGlobalBranchScope] = useSharedCommercialFilter('branchScope');
  const [globalPeriodMode, setGlobalPeriodMode] = useSharedCommercialFilter('periodMode');
  const [globalBrand, setGlobalBrand] = useSharedCommercialFilter('brand');
  const [globalBranchType, setGlobalBranchType] = useSharedCommercialFilter('branchType');
  const effectiveBranchType=globalBranchType==='SEMINUEVOS'?'SEMINUEVOS':'NUEVOS';
  const [exportingView,setExportingView]=useState(false);
  const fileInputRef = useRef(null);
  const emptyBackupInputRef = useRef(null);

  // ---- carga inicial ----
  useEffect(() => {
    (async () => {
      try {
        let recs = null, tms = null, tgs = null, usrs = null, locks = [], bdc = [], industry = null, amda = null, geo = null, branches = null, cutoff = '';
        const readStored = async (key, shared = true) => {
          try {
            const result = await window.storage.get(key, shared);
            return result?.value ?? null;
          } catch {
            return null;
          }
        };
        const [
          recordsValue, teamsValue, targetsValue, usersValue, locksValue,
          bdcValue, industryValue, amdaValue, geoValue, branchesValue, cutoffValue, sessionValue
        ] = await Promise.all([
          readStored(STORAGE_KEY), readStored(TEAMS_KEY), readStored(TARGETS_KEY),
          readStored(USERS_KEY), readStored(LOCKS_KEY), readStored(BDC_KEY),
          readStored(INDUSTRY_KEY), readStored(AMDA_KEY), readStored(GEOINTELLIGENCE_KEY), readStored(BRANCHES_KEY), readStored(CUTOFF_KEY),
          readStored(SESSION_KEY, false)
        ]);
        const parseStored = (value, fallback = null) => {
          if (value == null) return fallback;
          try { return JSON.parse(value); } catch { return fallback; }
        };
        recs = parseStored(recordsValue);
        tms = parseStored(teamsValue);
        tgs = parseStored(targetsValue);
        usrs = parseStored(usersValue);
        locks = parseStored(locksValue, []);
        bdc = parseStored(bdcValue, []);
        industry = parseStored(industryValue);
        amda = parseStored(amdaValue);
        geo = parseStored(geoValue);
        branches = parseStored(branchesValue);
        cutoff = cutoffValue || '';

        // La sesión autenticada ya está disponible localmente; no bloquea la
        // carga esperando otra consulta al servidor.
        let savedSession = parseStored(sessionValue);
        if (!savedSession && authenticatedSession) savedSession = authenticatedSession;

        if (!recs) {
          recs = SEED_DATA.map((r, i) => ({ id: `seed-${i}`, ...r }));
          if (authenticatedSession?.role === 'admin') {
            if (typeof window.storage.replaceRecords === 'function') await window.storage.replaceRecords(recs);
            else await window.storage.set(STORAGE_KEY, JSON.stringify(recs), true);
          }
        }
        if (!tms) {
          const bySucursal = {};
          for (const r of recs) {
            const key = r.sucursal || 'Juventud';
            if (!bySucursal[key]) bySucursal[key] = {};
            if (!bySucursal[key][r.manager]) bySucursal[key][r.manager] = new Set();
            bySucursal[key][r.manager].add(r.vendor);
          }
          tms = [];
          for (const [suc, managers] of Object.entries(bySucursal)) {
            for (const [manager, vendorSet] of Object.entries(managers)) {
              tms.push({ sucursal: suc, manager, vendors: Array.from(vendorSet), inactiveVendors: [] });
            }
          }
          if (authenticatedSession?.role === 'admin') await window.storage.set(TEAMS_KEY, JSON.stringify(tms), true);
        }
        recs = dedupeApvRecords(applyHistoricalManagerMigrations(recs));
        tms = dedupeApvTeams(tms.map(t => ({ ...t, inactiveVendors: t.inactiveVendors || [] })));
        const eliuJuventud=tms.find(team=>apvIdentity(team.sucursal)===apvIdentity('Juventud')&&apvIdentity(team.manager)===apvIdentity('ELIU QUINTANA'));
        if(eliuJuventud){
          eliuJuventud.vendors=uniqueApvNames([...(eliuJuventud.vendors||[]),'ANDY PADILLA','FERNANDA CANDANEDO']);
          eliuJuventud.inactiveVendors=(eliuJuventud.inactiveVendors||[]).filter(name=>!['ANDY PADILLA','FERNANDA CANDANEDO'].some(active=>apvIdentity(active)===apvIdentity(name)));
        }
        // Persistir la limpieza corrige también los duplicados históricos.
        // Abrir la plataforma no debe reescribir toda la base compartida.
        // Esto evita fallos por permisos, tamaño y sesiones concurrentes.
        if (!tgs) {
          tgs = DEFAULT_TARGETS;
          if (authenticatedSession?.role === 'admin') await window.storage.set(TARGETS_KEY, JSON.stringify(tgs), true);
        }
        // En la versión Supabase la sesión ya fue autenticada antes de montar
        // esta aplicación. Si falla la lectura del catálogo de usuarios,
        // conservamos el perfil autenticado y nunca restauramos el admin local.
        if (!usrs) {
          usrs = savedSession ? [savedSession] : [DEFAULT_ADMIN];
          if (!savedSession && authenticatedSession?.role === 'admin') await window.storage.set(USERS_KEY, JSON.stringify(usrs), true);
        }

        setRecords(recs);
        setTeams(tms);
        setTargets(tgs);
        setUsers(usrs);
        setPeriodLocks(Array.isArray(locks) ? locks : []);
        setBdcRecords(Array.isArray(bdc) ? bdc : []);
        if (!industry) {
          try {
            const response = await fetch('/inegi-industry-seed.json');
            if (response.ok) {
              industry = await response.json();
              await window.storage.set(INDUSTRY_KEY, JSON.stringify(industry), true);
            }
          } catch (e) { console.error('No se pudo cargar el histórico de industria', e); }
        }
        setIndustryData(industry);
        setAmdaData(amda);
        if (!geo) {
          try {
            const response = await fetch('/geo-sales-seed.json');
            if (response.ok) {
              geo = await response.json();
              if (authenticatedSession?.role === 'admin') await window.storage.set(GEOINTELLIGENCE_KEY, JSON.stringify(geo), true);
            }
          } catch (e) { console.error('No se pudo cargar el histÃ³rico geocomercial', e); }
        }
        setGeoData(geo || { meta:{}, sales:[] });
        if (!cutoff) {
          const now = new Date();
          cutoff = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
          if (authenticatedSession?.role === 'admin') await window.storage.set(CUTOFF_KEY, cutoff, true);
        }
        setCutoffDate(cutoff);
        const hadBranchCatalog=Array.isArray(branches)&&branches.length>0;
        branches=dedupeBranchCatalog(hadBranchCatalog?branches:DEFAULT_BRANCH_CATALOG);
        const knownNames=new Set(branches.map(branch=>apvIdentity(branch.name)));
        const discovered=[...new Set([...(recs||[]).map(r=>r.sucursal),...(tms||[]).map(t=>t.sucursal)].filter(Boolean))].filter(name=>!knownNames.has(apvIdentity(name)));
        branches=dedupeBranchCatalog([...branches,...discovered.map((name,index)=>({id:`branch-discovered-${index}-${Date.now()}`,name,type:'NUEVOS',brand:name.startsWith('CHS ')?'CHS':'CHEVROLET',active:true,order:999+index}))]);
        setBranchCatalog(branches);
        if (authenticatedSession?.role === 'admin' && (!hadBranchCatalog || discovered.length)) {
          await window.storage.set(BRANCHES_KEY,JSON.stringify(branches),true);
        }

        if (savedSession?.active !== false) {
          // Supabase ya validó credenciales, estado y permisos. No se solicita
          // una segunda contraseña perteneciente al sistema anterior.
          setSession(savedSession);
          applySucursalForRole(savedSession, recs);
          setView(savedSession.role === 'bdc_operador' ? 'bdc' : 'dashboard');
        }
      } catch (e) {
        console.error('Error cargando datos', e);
        setRecords(SEED_DATA.map((r, i) => ({ id: `seed-${i}`, ...r })));
        setTeams([]);
        setUsers([DEFAULT_ADMIN]);
      } finally {
        setLoading(false);
      }
    })();
  }, [authenticatedSession]);

  // Ajusta sucursal y mes inicial según rol del usuario
  function applySucursalForRole(sess, recs) {
    const suc = sess.sucursal || sess.branches?.[0] || 'Juventud';
    setSucursal(suc);
    const months = Array.from(new Set((recs || []).filter(r => r.sucursal === suc).map(r => r.month))).sort();
    setSelectedMonth(months[months.length - 1] || null);
  }

  const login = async (username, password, usersList) => {
    const list = usersList || users || [DEFAULT_ADMIN];
    const user = list.find(u => u.username === username && u.password === password && u.active !== false);
    if (!user) return false;
    setSession(user);
    applySucursalForRole(user, records);
    setView(user.role === 'bdc_operador' ? 'bdc' : 'dashboard');
    try { await window.storage.set(SESSION_KEY, JSON.stringify(user), false); } catch (e) {}
    return true;
  };

  const logout = async () => {
    try {
      await window.storage.delete(SESSION_KEY, false);
    } catch (e) {
      console.error('No fue posible cerrar la sesión en Supabase', e);
    } finally {
      setSession(null);
    }
  };

  const persistRecords = useCallback(async (next) => {
    const unique = dedupeApvRecords(applyHistoricalManagerMigrations(next));
    if (typeof window.storage.replaceRecords === 'function') await window.storage.replaceRecords(unique);
    else await window.storage.set(STORAGE_KEY, JSON.stringify(unique), true);
    setRecords(unique);
  }, []);

  const persistTeams = useCallback(async (next) => {
    const unique = dedupeApvTeams(next);
    await window.storage.set(TEAMS_KEY, JSON.stringify(unique), true);
    setTeams(unique);
  }, []);

  const persistTargets = useCallback(async (next) => {
    await window.storage.set(TARGETS_KEY, JSON.stringify(next), true);
    setTargets(next);
  }, []);

  const persistUsers = useCallback(async (next) => {
    await window.storage.set(USERS_KEY, JSON.stringify(next), true);
    setUsers(next.map(user => {
      const { password, confirmPassword, ...safeUser } = user;
      return safeUser;
    }));
  }, []);

  const persistPeriodLocks = useCallback(async (next) => {
    setPeriodLocks(next);
    await window.storage.set(LOCKS_KEY, JSON.stringify(next), true);
  }, []);

  const persistBdcRecords = useCallback(async (next) => {
    setBdcRecords(next);
    await window.storage.set(BDC_KEY, JSON.stringify(next), true);
  }, []);
  const persistIndustryData = useCallback(async next => {
    setIndustryData(next);
    await window.storage.set(INDUSTRY_KEY, JSON.stringify(next), true);
  }, []);
  const persistAmdaData = useCallback(async next => {
    setAmdaData(next);
    await window.storage.set(AMDA_KEY, JSON.stringify(next), true);
  }, []);
  const persistGeoData = useCallback(async next => {
    setGeoData(next);
    await window.storage.set(GEOINTELLIGENCE_KEY, JSON.stringify(next), true);
  }, []);
  const persistBranchCatalog = useCallback(async next => {const unique=dedupeBranchCatalog(next);setBranchCatalog(unique);await window.storage.set(BRANCHES_KEY,JSON.stringify(unique),true);},[]);
  const persistCutoffDate = useCallback(async value => {setCutoffDate(value);await window.storage.set(CUTOFF_KEY,value,true);},[]);

  const showToast = (msg, type = 'ok') => { setToast({ msg, type }); setTimeout(() => setToast(null), 3200); };
  const exportTitle=view==='dashboard'?'Resumen Ejecutivo':view==='comparativos'?'Pulso Comercial':view==='catalogos'?'Catálogos':'Usuarios';
  const exportScope=`${selectedMonth?monthLabel(selectedMonth):''} · ${globalBranchScope==='todas'?'Todas las sucursales':sucursal} · ${globalPeriodMode==='accumulated'?'Acumulado':'Mensual'}`;
  const exportViewPdf=()=>{const previous=document.title;document.title=`${view==='dashboard'?'Resumen Ejecutivo':view==='comparativos'?'Pulso Comercial':view==='catalogos'?'Catálogos':'Usuarios'} - ${selectedMonth?monthLabel(selectedMonth):''}`;document.body.classList.add('general-export-print');window.print();setTimeout(()=>{document.body.classList.remove('general-export-print');document.title=previous;},600);};
  const exportViewPpt=async()=>{try{setExportingView(true);const [{default:html2canvas},{default:PptxGenJS}]=await Promise.all([import('html2canvas'),import('pptxgenjs')]);const target=document.querySelector('.main-area');if(!target)return;const canvas=await html2canvas(target,{scale:1.35,backgroundColor:'#F4F7FB',useCORS:true,ignoreElements:element=>element.classList?.contains('executive-export-toolbar')});const pptx=new PptxGenJS();pptx.layout='LAYOUT_WIDE';pptx.author='Grupo CR3';pptx.subject='Inteligencia comercial';pptx.title=view==='dashboard'?'Resumen Ejecutivo':view==='comparativos'?'Pulso Comercial':view==='catalogos'?'Catálogos':'Usuarios';const pageHeight=Math.floor(canvas.width/1.92);for(let offset=0,page=1;offset<canvas.height;offset+=pageHeight,page++){const crop=document.createElement('canvas');crop.width=canvas.width;crop.height=Math.min(pageHeight,canvas.height-offset);crop.getContext('2d').drawImage(canvas,0,offset,canvas.width,crop.height,0,0,canvas.width,crop.height);const slide=pptx.addSlide();slide.background={color:'F4F7FB'};slide.addShape(pptx.ShapeType.rect,{x:0,y:0,w:13.333,h:.62,fill:{color:'102B57'},line:{color:'102B57'}});slide.addImage({data:LOGO_CR3,x:.28,y:.08,w:.75,h:.38});slide.addImage({data:LOGO_MARCAS,x:1.1,y:.14,w:1.65,h:.27});slide.addText(`${pptx.title} · ${selectedMonth?monthLabel(selectedMonth):''}`,{x:7.3,y:.15,w:5.6,h:.24,fontFace:'Aptos',fontSize:13,bold:true,color:'FFFFFF',align:'right'});slide.addImage({data:crop.toDataURL('image/png'),x:.25,y:.76,w:12.83,h:6.45});slide.addText(String(page),{x:12.55,y:7.23,w:.35,h:.12,fontSize:7,color:'64748B',align:'right'});}await pptx.writeFile({fileName:`${pptx.title.replace(/\s+/g,'_')}_${selectedMonth||'reporte'}.pptx`});showToast('Presentación PowerPoint generada.');}catch(error){console.error(error);showToast('No fue posible generar la presentación.','error');}finally{setExportingView(false);}};
  const exportViewPptPortrait=async()=>{try{setExportingView(true);const [{default:html2canvas},{default:PptxGenJS}]=await Promise.all([import('html2canvas'),import('pptxgenjs')]);const target=document.querySelector('.main-area');if(!target)return;const canvas=await html2canvas(target,{scale:1.25,backgroundColor:'#F4F7FB',useCORS:true,ignoreElements:element=>element.classList?.contains('executive-export-toolbar')});const pptx=new PptxGenJS();pptx.defineLayout({name:'LETTER_PORTRAIT',width:8.5,height:11});pptx.layout='LETTER_PORTRAIT';pptx.author='Grupo CR3';pptx.subject='Inteligencia comercial';pptx.title=view==='dashboard'?'Resumen Ejecutivo':view==='comparativos'?'Pulso Comercial':view==='catalogos'?'Catálogos':'Usuarios';const contentWidth=7.9,contentHeight=9.75,pageHeight=Math.floor(canvas.width/(contentWidth/contentHeight));for(let offset=0,page=1;offset<canvas.height;offset+=pageHeight,page++){const crop=document.createElement('canvas');crop.width=canvas.width;crop.height=Math.min(pageHeight,canvas.height-offset);crop.getContext('2d').drawImage(canvas,0,offset,canvas.width,crop.height,0,0,canvas.width,crop.height);const slide=pptx.addSlide();slide.background={color:'F4F7FB'};slide.addShape(pptx.ShapeType.rect,{x:0,y:0,w:8.5,h:.68,fill:{color:'102B57'},line:{color:'102B57'}});slide.addImage({data:LOGO_CR3,x:.25,y:.1,w:.72,h:.38});slide.addImage({data:LOGO_MARCAS,x:1.08,y:.16,w:1.5,h:.25});slide.addText(`${pptx.title} · ${selectedMonth?monthLabel(selectedMonth):''}`,{x:3.05,y:.17,w:5.05,h:.25,fontFace:'Aptos',fontSize:11,bold:true,color:'FFFFFF',align:'right'});const renderedHeight=Math.min(contentHeight,crop.height/crop.width*contentWidth);slide.addImage({data:crop.toDataURL('image/png'),x:.3,y:.82,w:contentWidth,h:renderedHeight});slide.addText(String(page),{x:7.85,y:10.7,w:.3,h:.12,fontSize:7,color:'64748B',align:'right'});}await pptx.writeFile({fileName:`${pptx.title.replace(/\s+/g,'_')}_${selectedMonth||'reporte'}_Carta_Vertical.pptx`});showToast('Presentación Carta vertical generada.');}catch(error){console.error(error);showToast('No fue posible generar la presentación.','error');}finally{setExportingView(false);}};

  // Records filtrados según rol del usuario activo
  const exportViewPptExecutive=async()=>{
    try{
      setExportingView(true);
      const [{default:html2canvas},{default:PptxGenJS}]=await Promise.all([import('html2canvas'),import('pptxgenjs')]);
      const target=document.querySelector('.main-area');
      if(!target)return;
      const canvas=await html2canvas(target,{scale:1.45,backgroundColor:'#F4F7FB',useCORS:true,ignoreElements:element=>element.classList?.contains('executive-export-toolbar')});
      const pptx=new PptxGenJS();
      pptx.layout='LAYOUT_WIDE';
      pptx.author='Grupo CR3'; pptx.company='Grupo CR3'; pptx.subject='Funnel de inteligencia comercial'; pptx.title=exportTitle; pptx.lang='es-MX';
      pptx.theme={headFontFace:'Aptos Display',bodyFontFace:'Aptos',lang:'es-MX'};
      const addFrame=(slide,page)=>{
        slide.background={color:'FFFFFF'};
        slide.addShape(pptx.ShapeType.roundRect,{x:.16,y:.14,w:13.01,h:7.14,rectRadius:.06,fill:{color:'FFFFFF',transparency:100},line:{color:'173B69',width:1.4}});
        slide.addShape(pptx.ShapeType.line,{x:.36,y:7.06,w:12.6,h:0,line:{color:'1E5AA8',width:8}});
        slide.addImage({data:LOGO_CR3,x:.42,y:.28,w:.62,h:.32});
        slide.addImage({data:LOGO_MARCAS,x:1.16,y:.32,w:1.42,h:.23});
        slide.addText(String(page),{x:12.55,y:7.12,w:.25,h:.12,fontFace:'Aptos',fontSize:6,color:'64748B',align:'right'});
      };
      const cover=pptx.addSlide();
      addFrame(cover,1);
      cover.addShape(pptx.ShapeType.roundRect,{x:.48,y:1.36,w:12.36,h:4.62,rectRadius:.08,fill:{color:'16345F'},line:{color:'16345F'}});
      cover.addShape(pptx.ShapeType.rect,{x:.48,y:5.45,w:12.36,h:.53,fill:{color:'16A9DF'},line:{color:'16A9DF'}});
      cover.addText('PLATAFORMA FUNNEL DE INTELIGENCIA COMERCIAL',{x:.92,y:1.88,w:10.8,h:.34,fontFace:'Aptos',fontSize:14,bold:true,color:'7DD3FC',charSpacing:1.2});
      cover.addText(exportTitle.toUpperCase(),{x:.92,y:2.42,w:10.8,h:.78,fontFace:'Aptos Display',fontSize:34,bold:true,italic:true,color:'FFFFFF',margin:0});
      cover.addText(exportScope,{x:.92,y:3.42,w:10.8,h:.38,fontFace:'Aptos',fontSize:17,bold:true,color:'FFFFFF'});
      cover.addText('Reporte ejecutivo generado con los filtros activos de la plataforma.',{x:.92,y:4.14,w:9.7,h:.32,fontFace:'Aptos',fontSize:12,color:'DCE9FA'});
      cover.addText(`Generado el ${new Date().toLocaleDateString('es-MX',{day:'2-digit',month:'long',year:'numeric'})}`,{x:.92,y:4.68,w:9.7,h:.24,fontFace:'Aptos',fontSize:9,color:'B8C9E3'});
      const contentX=.48,contentY=1.03,contentW=12.36,contentH=5.78;
      const idealPagePx=Math.floor(canvas.width/(contentW/contentH));
      const scaleY=canvas.height/Math.max(target.scrollHeight,1);
      const breakpoints=[...target.querySelectorAll(':scope > *,.card,.panel,section')].map(el=>Math.round((el.offsetTop+el.offsetHeight)*scaleY)).filter(value=>value>80&&value<canvas.height).sort((a,b)=>a-b);
      let offset=0,page=2;
      while(offset<canvas.height){
        const ideal=Math.min(canvas.height,offset+idealPagePx);
        const candidates=breakpoints.filter(point=>point>offset+idealPagePx*.52&&point<=ideal);
        const end=ideal===canvas.height?canvas.height:(candidates[candidates.length-1]||ideal);
        const crop=document.createElement('canvas'); crop.width=canvas.width; crop.height=Math.max(1,end-offset);
        crop.getContext('2d').drawImage(canvas,0,offset,canvas.width,crop.height,0,0,canvas.width,crop.height);
        const slide=pptx.addSlide(); addFrame(slide,page);
        slide.addShape(pptx.ShapeType.roundRect,{x:.5,y:.35,w:8.3,h:.46,rectRadius:.05,fill:{color:'173B69'},line:{color:'173B69'}});
        slide.addText(`${exportTitle} · ${exportScope}`,{x:.7,y:.45,w:11.4,h:.2,fontFace:'Aptos Display',fontSize:13,bold:true,italic:true,color:'FFFFFF',margin:0});
        const renderedH=Math.min(contentH,crop.height/crop.width*contentW);
        slide.addImage({data:crop.toDataURL('image/png'),x:contentX,y:contentY,w:contentW,h:renderedH});
        if(renderedH<contentH-.35)slide.addText('Interpretación / acuerdos:',{x:contentX,y:contentY+renderedH+.15,w:contentW,h:.25,fontFace:'Aptos',fontSize:10,bold:true,color:'173B69'});
        offset=end; page++;
      }
      await pptx.writeFile({fileName:`${exportTitle.replace(/\s+/g,'_')}_${selectedMonth||'reporte'}_Ejecutivo.pptx`});
      showToast('Presentación ejecutiva generada.');
    }catch(error){console.error(error);showToast('No fue posible generar la presentación.','error');}
    finally{setExportingView(false);}
  };

  const homologatedRecords = useMemo(() => mergeBdcMetricsIntoFunnel(records || [], bdcRecords), [records, bdcRecords]);
  const visibleRecords = useMemo(() => filterBySession(homologatedRecords, session, branchCatalog), [homologatedRecords, session, branchCatalog]);
  const visibleBdcRecords = useMemo(() => filterBdcBySession(bdcRecords, session, branchCatalog), [bdcRecords, session, branchCatalog]);

  // Periodos disponibles. El selector muestra los 12 meses del año elegido para
  // permitir capturar periodos que todavía no existen en una importación.
  const dataMonths = useMemo(() => {
    if (!visibleRecords) return [];
    const branchNames=branchCatalog.filter(branch=>branch.active!==false&&(globalBrand==='todas'||branch.brand===globalBrand)&&branch.type===effectiveBranchType).map(branch=>branch.name);
    const filtered=(visibleRecords||[]).filter(record=>branchNames.includes(record.sucursal));
    const scoped = globalBranchScope === 'todas' ? filtered : filtered.filter(r => r.sucursal === sucursal);
    return Array.from(new Set(scoped.map(r => r.month))).sort();
  }, [visibleRecords, sucursal, globalBranchScope, branchCatalog, globalBrand, effectiveBranchType]);
  const availableYears = useMemo(() => {
    const current = new Date().getFullYear();
    const recordYears = (visibleRecords || []).map(r => Number(r.month?.slice(0,4))).filter(Boolean);
    const min = Math.min(current - 10, ...(recordYears.length ? recordYears : [current]));
    const max = Math.max(current + 1, ...(recordYears.length ? recordYears : [current]));
    return Array.from({length:max-min+1},(_,index)=>String(max-index));
  }, [visibleRecords]);
  const selectedYear = selectedMonth?.slice(0,4) || dataMonths[dataMonths.length-1]?.slice(0,4) || String(new Date().getFullYear());
  const months = useMemo(() => Array.from({length:12},(_,index)=>`${selectedYear}-${String(index+1).padStart(2,'0')}`), [selectedYear]);

  useEffect(() => {
    if (!selectedMonth) setSelectedMonth(dataMonths[dataMonths.length - 1] || `${new Date().getFullYear()}-${String(new Date().getMonth()+1).padStart(2,'0')}`);
  }, [dataMonths, selectedMonth]);

  const catalogBranches = useMemo(() => branchCatalog.filter(branch=>branch.active!==false).sort((a,b)=>(a.order??999)-(b.order??999)),[branchCatalog]);
  const filteredCatalogBranches = useMemo(() => catalogBranches.filter(branch=>(globalBrand==='todas'||branch.brand===globalBrand)&&branch.type===effectiveBranchType),[catalogBranches,globalBrand,effectiveBranchType]);
  const filteredBranchNames=useMemo(()=>filteredCatalogBranches.map(branch=>branch.name),[filteredCatalogBranches]);
  const commercialRecords=useMemo(()=>(visibleRecords||[]).filter(record=>filteredBranchNames.includes(record.sucursal)),[visibleRecords,filteredBranchNames]);
  const teamsForSucursal = useMemo(() => (teams || []).filter(t => t.sucursal === sucursal), [teams, sucursal]);
  const globalFilterRecords = useMemo(() => commercialRecords.filter(record =>
    globalBranchScope === 'todas' || record.sucursal === sucursal), [commercialRecords, globalBranchScope, sucursal]);
  const activeFilterTeams = useMemo(() => (teams || []).filter(team =>
    !team.inactiveManager && filteredBranchNames.includes(team.sucursal) &&
    (globalBranchScope === 'todas' || team.sucursal === sucursal)
  ), [teams, filteredBranchNames, globalBranchScope, sucursal]);
  const globalManagers = useMemo(() => [...new Set(activeFilterTeams.map(team => team.manager).filter(Boolean))]
    .sort((a,b) => a.localeCompare(b,'es')), [activeFilterTeams]);
  const globalVendors = useMemo(() => uniqueApvNames(activeFilterTeams
    .filter(team => globalManager === 'todos' || team.manager === globalManager)
    .flatMap(team => (team.vendors || []).filter(vendor =>
      !(team.inactiveVendors || []).some(inactive => apvIdentity(inactive) === apvIdentity(vendor))
    ))).sort((a,b) => a.localeCompare(b,'es')), [activeFilterTeams, globalManager]);

  // Sucursales permitidas según rol
  const allowedSucursales = useMemo(() => {
    const permitted = new Set(sessionAllowedBranchNames(session,branchCatalog).map(apvIdentity));
    return filteredBranchNames.filter(name=>permitted.has(apvIdentity(name)));
  }, [session,filteredBranchNames,branchCatalog]);

  useEffect(() => {
    if (allowedSucursales.length && !allowedSucursales.includes(sucursal)) setSucursal(allowedSucursales[0]);
  }, [allowedSucursales, sucursal]);

  // Vistas permitidas: customViews del usuario (si existe) tiene precedencia sobre el rol
  const allowedViews = useMemo(() => {
    if (!session) return [];
    if (session.role === 'bdc_operador') return ['bdc'];
    if (session.customViews && session.customViews.length > 0) {
      const storedViews = session.customViews.filter(viewKey => !['seminuevos', 'planeacion'].includes(viewKey));
      // Los perfiles existentes se guardaron antes de crear esta pestaña.
      // Si ya tenían Industria, incorporamos automáticamente Geointeligencia.
      const currentViews = storedViews.includes('industria')
        ? [...new Set([...storedViews, 'geointeligencia'])]
        : storedViews;
      return session.role === 'admin'
        ? [...new Set([...currentViews, 'geointeligencia', 'catalogos', 'admin'])]
        : (currentViews.length ? currentViews : (VIEWS_BY_ROLE[session.role] || ['dashboard']));
    }
    return VIEWS_BY_ROLE[session.role] || ['dashboard'];
  }, [session]);

  useEffect(() => {
    if (session && allowedViews.length && !allowedViews.includes(view)) setView(allowedViews[0]);
  }, [session, allowedViews, view]);

  // Importador de Excel (solo admin y capturista)
  const handleFileImport = async (file) => {
    try {
      const XLSX = await import('xlsx');
      const buf = await file.arrayBuffer();
      const wb = XLSX.read(buf, { type: 'array' });
      const normalizeText = (value) => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
      let sheetName = wb.SheetNames.find(n => normalizeText(n) === 'carga historica')
        || wb.SheetNames.find(n => /juventud|universidad|estadio|delicias|cuauht|parral|camargo|manitoba|jimenez|jim[eé]nez|ojinaga|chs/i.test(n))
        || wb.SheetNames[0];
      const ws = wb.Sheets[sheetName];
      const rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: null });
      const titleRowPre = rows.slice(0, 4).map(r => (r || []).join(' ')).join(' ');
      const haystack = `${sheetName} ${titleRowPre}`.toLowerCase();
      const sucursalesPorLongitud = branchCatalog.filter(branch=>branch.active!==false).map(branch=>branch.name).sort((a, b) => b.length - a.length);
      const isSeminuevosSheet = /seminuevos|semi nuevos/i.test(haystack);
      const importBranchCandidates = branchCatalog
        .filter(branch => branch.active !== false && (!isSeminuevosSheet || branch.type === 'SEMINUEVOS'))
        .map(branch => branch.name)
        .sort((a,b) => b.length - a.length);
      const normalizedImportHaystack = normalizeText(haystack);
      const branchMatchName = name => {
        const normalized = normalizeText(name);
        const withoutType = normalized.replace(/\bseminuevos?\b/g,'').trim();
        return normalizedImportHaystack.includes(normalized)
          || (withoutType.length >= 4 && normalizedImportHaystack.includes(withoutType));
      };
      let detectedSucursal = importBranchCandidates.find(branchMatchName)
        || sucursalesPorLongitud.find(branchMatchName)
        || sucursal;
      const titleRow = titleRowPre;
      const monthMatch = titleRow.match(/(ENERO|FEBRERO|MARZO|ABRIL|MAYO|JUNIO|JULIO|AGOSTO|SEPTIEMBRE|OCTUBRE|NOVIEMBRE|DICIEMBRE)\s+(\d{4})/i);
      let detectedMonth = null;
      if (monthMatch) {
        const idx = MONTH_NAMES.findIndex(m => m.toUpperCase() === monthMatch[1].toUpperCase());
        if (idx >= 0) detectedMonth = `${monthMatch[2]}-${String(idx + 1).padStart(2, '0')}`;
      }
      if (!detectedMonth) { const today = new Date(); detectedMonth = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}`; }
      let headerRowIdx = -1, colMap = {};
      const fieldAliases = {
        llamadas: ['llamadas'], freshUp: ['fresh-up', 'fresh up', 'freshup'], calle: ['calle'],
        reactivaciones: ['reactivaciones'], fanpageApv: ['fanpage apv', 'fanpage', 'digitales'],
        citasLeadIt: ['citas efectivas lead-it', 'lead-it'], citasFbToro: ['citas efectivas fb toro', 'fb toro'],
        demos: ['demos'], solicitudes: ['solicitudes/gmf', 'solicitudes'], avaluos: ['avalúos', 'avaluos'],
        tomas: ['tomas'], seguros: ['seguros'], ventasSeminuevos: ['ventas seminuevos'],
        ventasLeadIt: ['ventas lead-it'], ventasFb: ['ventas fb'], ventasFanpageApv: ['ventas fanpage apv', 'ventas fanpage'],
        ventasTotales: ['ventas totales'], entregas: ['entregas'],
      };
      for (let r = 0; r < Math.min(rows.length, 20); r++) {
        const row = rows[r] || [];
        const norm = row.map(c => (c || '').toString().toLowerCase().trim());
        let hits = 0; const tmpMap = {};
        for (const [key, aliases] of Object.entries(fieldAliases)) {
          const ci = norm.findIndex(c => aliases.some(a => c.includes(a)));
          if (ci >= 0) { tmpMap[key] = ci; hits++; }
        }
        const exactVentas = norm.findIndex(c => normalizeText(c) === 'ventas');
        if (exactVentas >= 0) tmpMap.ventasTotales = exactVentas;
        if (hits >= 5) { headerRowIdx = r; colMap = tmpMap; break; }
      }
      if (headerRowIdx === -1) { showToast('No se reconoció el formato del Excel.', 'error'); return; }
      const headerRow = (rows[headerRowIdx] || []).map(c => (c || '').toString().toLowerCase());
      const sucursalCol = headerRow.findIndex(c => normalizeText(c) === 'sucursal');
      const monthCol = headerRow.findIndex(c => ['mes','periodo','período'].includes(c.trim().toLowerCase()));
      let managerCol = headerRow.findIndex(c => c.includes('gerente'));
      let vendorCol = headerRow.findIndex(c => c.includes('asesor') || c.includes('vendedor'));
      if (vendorCol === -1) vendorCol = 2;
      if (managerCol === -1) managerCol = vendorCol > 0 ? vendorCol - 1 : 1;
      const newRecords = [];
      let currentManager = null;
      const parseMonthValue = (value) => {
        if (value instanceof Date && !Number.isNaN(value.getTime())) return `${value.getFullYear()}-${String(value.getMonth()+1).padStart(2,'0')}`;
        if (typeof value === 'number') {
          const parsed = XLSX.SSF.parse_date_code(value);
          if (parsed?.y && parsed?.m) return `${parsed.y}-${String(parsed.m).padStart(2,'0')}`;
        }
        const text = String(value ?? '').trim();
        const iso = text.match(/^(20\d{2})[-\/]([01]?\d)$/);
        if (iso && Number(iso[2]) >= 1 && Number(iso[2]) <= 12) return `${iso[1]}-${String(Number(iso[2])).padStart(2,'0')}`;
        const named = text.match(/(ENERO|FEBRERO|MARZO|ABRIL|MAYO|JUNIO|JULIO|AGOSTO|SEPTIEMBRE|OCTUBRE|NOVIEMBRE|DICIEMBRE)\s+(20\d{2})/i);
        if (named) return `${named[2]}-${String(MONTH_NAMES.findIndex(m => normalizeText(m) === normalizeText(named[1])) + 1).padStart(2,'0')}`;
        return null;
      };
      const canonicalSucursal = (value) => sucursalesPorLongitud.find(s => normalizeText(s) === normalizeText(value)) || null;
      for (let r = headerRowIdx + 1; r < rows.length; r++) {
        const row = rows[r] || [];
        if (row.every(c => c === null || c === '')) continue;
        const mgr = row[managerCol]; const vnd = row[vendorCol];
        if (mgr && typeof mgr === 'string' && mgr.trim()) currentManager = mgr.trim().toUpperCase();
        if (!vnd || typeof vnd !== 'string') continue;
        const vendorName = vnd.trim().toUpperCase();
        if (!vendorName || /total|adicional/i.test(vendorName)) continue;
        const rowSucursal = sucursalCol >= 0 ? canonicalSucursal(row[sucursalCol]) : detectedSucursal;
        const rowMonth = monthCol >= 0 ? parseMonthValue(row[monthCol]) : detectedMonth;
        if (!rowSucursal || !rowMonth) continue;
        const rec = { sucursal: rowSucursal, month: rowMonth, manager: currentManager || 'SIN ASIGNAR', vendor: vendorName };
        for (const [key, ci] of Object.entries(colMap)) {
          const v = row[ci]; rec[key] = typeof v === 'number' ? v : (parseFloat(v) || 0);
        }
        for (const f of BASE_FIELDS) if (!(f.key in rec)) rec[f.key] = 0;
        newRecords.push(rec);
      }
      const uniqueRecords = dedupeApvRecords(newRecords);
      if (!uniqueRecords.length) { showToast('No se encontraron filas válidas.', 'error'); return; }
      const importedPeriods = new Set(uniqueRecords.map(r => `${r.sucursal}||${r.month}`));
      const filtered = records.filter(r => !importedPeriods.has(`${r.sucursal}||${r.month}`));
      const withIds = uniqueRecords.map((r, i) => ({ id: `import-${Date.now()}-${i}`, ...r }));
      const mergedRecords = dedupeApvRecords(applyHistoricalManagerMigrations([...filtered, ...withIds]));
      if (typeof window.storage.importRecords === 'function') {
        await window.storage.importRecords(withIds);
        setRecords(mergedRecords);
      } else {
        await persistRecords(mergedRecords);
      }
      const teamMap = {};
      for (const r of withIds) {
        const k = `${r.sucursal}::${r.manager}`;
        if (!teamMap[k]) teamMap[k] = { sucursal: r.sucursal, manager: r.manager, vendors: new Set() };
        teamMap[k].vendors.add(r.vendor);
      }
      let nextTeams = [...teams];
      for (const t of Object.values(teamMap)) {
        const idx = nextTeams.findIndex(x => x.sucursal === t.sucursal && x.manager === t.manager);
        if (idx >= 0) nextTeams[idx] = { ...nextTeams[idx], vendors: uniqueApvNames([...nextTeams[idx].vendors, ...t.vendors]) };
        else nextTeams.push({ sucursal: t.sucursal, manager: t.manager, vendors: Array.from(t.vendors), inactiveVendors: [] });
      }
      await persistTeams(dedupeApvTeams(nextTeams));
      const lastImported = withIds[withIds.length - 1];
      setSucursal(lastImported.sucursal);
      setSelectedMonth(lastImported.month);
      const importedBranches = new Set(withIds.map(r => r.sucursal)).size;
      showToast(`Importados ${uniqueRecords.length} APV únicos · ${importedPeriods.size} periodos · ${importedBranches} sucursal${importedBranches === 1 ? '' : 'es'}`);
    } catch (e) {
      console.error(e);
      showToast(`No se pudo guardar la importación: ${e?.message || 'error desconocido'}`, 'error');
    }
  };

  if (loading || !records || !teams) {
    return (
      <div className="boot-screen">
        <Loader2 className="spin" size={26} />
        <span>Cargando plataforma…</span>
        <style>{GLOBAL_CSS}</style>
      </div>
    );
  }

  // Sin sesión → pantalla de login
  if (!session && !authenticatedSession) {
    return (
      <div className="app-root">
        <style>{GLOBAL_CSS}</style>
        <LoginScreen users={users || [DEFAULT_ADMIN]} onLogin={login} />
      </div>
    );
  }

  // Una base recién creada en Supabase no debe intentar construir todos los
  // tableros todavía. Esta pantalla mínima permite restaurar el respaldo sin
  // montar gráficas, comparativos o tablas sobre arreglos vacíos.
  if (records.length === 0) {
    return (
      <div className="empty-migration-screen">
        <style>{GLOBAL_CSS}</style>
        <div className="empty-migration-card">
          <div className="empty-migration-logos">
            <img src={LOGO_CR3} alt="Grupo CR3" />
            <img src={LOGO_MARCAS} alt="Chevrolet, Buick, GMC y Cadillac" />
          </div>
          <span className="eyebrow"><Database size={14}/> Recuperación inicial</span>
          <h1>Supabase está listo para recibir tu información</h1>
          <p>
            La base nueva todavía no tiene registros comerciales. Selecciona el
            respaldo completo descargado desde la plataforma anterior.
          </p>
          <button className="import-btn empty-migration-button" onClick={() => emptyBackupInputRef.current?.click()}>
            <Upload size={17}/> Migrar respaldo completo
          </button>
          <input
            ref={emptyBackupInputRef}
            hidden
            type="file"
            accept=".json,application/json"
            onChange={async event => {
              const file = event.target.files?.[0];
              event.target.value = '';
              if (!file) return;
              try {
                await importCompleteBackup(file);
                alert('La información se guardó correctamente en Supabase. La plataforma se recargará.');
                window.location.reload();
              } catch (error) {
                alert(error?.message || 'No fue posible migrar el respaldo.');
              }
            }}
          />
          <small>Esta operación incluye funnel, equipos, catálogos, metas, BDC e Industria.</small>
          <button className="empty-migration-logout" onClick={logout}>Cerrar sesión</button>
        </div>
        <style>{`
          .empty-migration-screen{min-height:100vh;display:grid;place-items:center;padding:28px;background:radial-gradient(circle at 85% 10%,#dbeafe,transparent 35%),#f3f6fb;font-family:Inter,Arial,sans-serif}
          .empty-migration-card{width:min(620px,100%);padding:38px;border:1px solid #dbe3ee;border-radius:24px;background:#fff;box-shadow:0 24px 70px rgba(15,35,66,.14);text-align:center}
          .empty-migration-logos{display:flex;align-items:center;justify-content:center;gap:28px;margin-bottom:24px}
          .empty-migration-logos img:first-child{width:120px;height:58px;object-fit:contain}
          .empty-migration-logos img:last-child{width:210px;height:52px;object-fit:contain}
          .empty-migration-card .eyebrow{justify-content:center;color:#2563eb}
          .empty-migration-card h1{margin:10px 0;color:#102b57;font-size:27px}
          .empty-migration-card p{max-width:470px;margin:0 auto 24px;color:#64748b;line-height:1.55}
          .empty-migration-button{width:100%;height:50px;justify-content:center;font-size:14px}
          .empty-migration-card small{display:block;margin-top:15px;color:#94a3b8}
          .empty-migration-logout{margin-top:18px;border:0;background:transparent;color:#64748b;text-decoration:underline;cursor:pointer}
        `}</style>
      </div>
    );
  }

  const canCapture = ROLES[session.role]?.canCapture || session.customCanCapture === true;
  const canCaptureGeneral = canCapture && session.role !== 'bdc_operador';
  const canManageUsers = ROLES[session.role]?.canManageUsers;

  return (
    <div className="app-root">
      <style>{GLOBAL_CSS}</style>
      <style>{EXPORT_CSS}</style>
      <style>{PORTRAIT_EXPORT_CSS}</style>
      <TopBar
        view={view} setView={setView}
        sucursal={sucursal} setSucursal={(s) => { if (allowedSucursales.includes(s)) setSucursal(s); }}
        allowedSucursales={allowedSucursales}
        allowedViews={allowedViews}
        session={session} onLogout={logout}
        onImportClick={() => canCaptureGeneral && fileInputRef.current?.click()}
        canCapture={canCaptureGeneral}
      />
      <StickyFilterController />
      <input ref={fileInputRef} type="file" accept=".xlsx,.xls" style={{ display: 'none' }}
        onChange={e => { const f = e.target.files?.[0]; if (f) handleFileImport(f); e.target.value = ''; }} />
      {!['bdc','industria','geointeligencia'].includes(view) && <CommercialFilterBar
        allowedSucursales={allowedSucursales} sucursal={sucursal} setSucursal={setSucursal}
        branchScope={globalBranchScope} setBranchScope={setGlobalBranchScope}
        months={months} years={availableYears} selectedMonth={selectedMonth} setSelectedMonth={setSelectedMonth}
        managers={globalManagers} manager={globalManager} setManager={setGlobalManager}
        vendors={globalVendors} vendor={globalVendor} setVendor={setGlobalVendor}
        periodMode={globalPeriodMode} setPeriodMode={setGlobalPeriodMode}
        brand={globalBrand} setBrand={setGlobalBrand} branchType={effectiveBranchType} setBranchType={setGlobalBranchType}
      />}
      <main className="main-area">
        {['dashboard','comparativos','catalogos','admin'].includes(view)&&<div className="executive-export-toolbar"><div><FileText size={15}/><span>Exportación ejecutiva</span><small>Formato horizontal · portada, filtros activos y diseño corporativo</small></div><div><button className="icon-btn" onClick={exportViewPdf}><Download size={14}/> PDF</button><button className="import-btn" disabled={exportingView} onClick={exportViewPptExecutive}>{exportingView?<Loader2 className="spin" size={14}/>:<FileBarChart2 size={14}/>} PowerPoint</button></div></div>}
        {view === 'dashboard' && (
          <Dashboard records={commercialRecords} allRecords={commercialRecords} branchNames={filteredBranchNames} branchCatalog={branchCatalog} branchType={effectiveBranchType} teams={teamsForSucursal} allTeams={teams} months={months} sucursal={sucursal}
            selectedMonth={selectedMonth} setSelectedMonth={setSelectedMonth} targets={targets}
            cutoffDate={cutoffDate} persistCutoffDate={persistCutoffDate}
            canEditCutoff={session.role === 'admin' || session.role === 'capturista'} />
        )}
        {view === 'comparativos' && allowedViews.includes('comparativos') && (
          <ComparativosView records={commercialRecords} months={months} branchNames={filteredBranchNames} sucursal={sucursal} targets={targets}
            selectedMonth={selectedMonth} setSelectedMonth={setSelectedMonth} teams={teamsForSucursal} />
        )}
        {view === 'capture' && allowedViews.includes('capture') && (
          <CaptureView records={homologatedRecords} bdcRecords={bdcRecords} teams={teamsForSucursal} sucursal={sucursal} month={selectedMonth}
            branchType={branchCatalog.find(branch=>apvIdentity(branch.name)===apvIdentity(sucursal))?.type||'NUEVOS'}
            persistRecords={persistRecords} persistTeams={(nextBranchTeams) => persistTeams([
              ...teams.filter(t => t.sucursal !== sucursal),
              ...nextBranchTeams,
            ])} targets={targets} showToast={showToast}
            periodLocks={periodLocks} persistPeriodLocks={persistPeriodLocks} session={session} />
        )}
        {view === 'history' && allowedViews.includes('history') && (
          <HistoryView records={commercialRecords} teams={teams} sucursal={sucursal} selectedMonth={selectedMonth} persistRecords={persistRecords}
            showToast={showToast} targets={targets} />
        )}
        {view === 'metas' && allowedViews.includes('metas') && (
          <MetasView targets={targets} persistTargets={persistTargets} showToast={showToast}
            branchNames={branchCatalog.filter(branch=>branch.active!==false).map(branch=>branch.name)}
            selectedMonth={selectedMonth} />
        )}
        {view === 'resumen' && allowedViews.includes('resumen') && (
          <ResumenEjecutivoView records={commercialRecords} teams={teams} months={months}
            sucursal={sucursal} selectedMonth={selectedMonth} setSelectedMonth={setSelectedMonth} targets={targets} />
        )}
        {view === 'bdc' && allowedViews.includes('bdc') && (
          <BdcView records={visibleBdcRecords} catalogTeams={teams.filter(team=>sessionAllowedBranchNames(session,branchCatalog).some(name=>apvIdentity(name)===apvIdentity(team.sucursal)))} branchCatalog={catalogBranches.filter(branch=>sessionAllowedBranchNames(session,branchCatalog).some(name=>apvIdentity(name)===apvIdentity(branch.name)))} persistRecords={async scopedNext=>{
            const allowed=new Set(sessionAllowedBranchNames(session,branchCatalog).map(apvIdentity));
            const merged=bdcRecords.map(original=>{const scoped=scopedNext.find(record=>record.period===original.period);if(!scoped)return original;return {...original,...scoped,sourceRows:[...(original.sourceRows||[]).filter(row=>!(scoped.sourceRows||[]).some(nextRow=>nextRow.brand===row.brand&&nextRow.source===row.source)),...(scoped.sourceRows||[])],apvs:[...(original.apvs||[]).filter(row=>!allowed.has(apvIdentity(row.branch))),...(scoped.apvs||[])],teams:[...(original.teams||[]).filter(row=>!allowed.has(apvIdentity(row.branch))),...(scoped.teams||[])],campaigns:[...(original.campaigns||[]).filter(row=>row.branch!=='Fuera del PMA'&&!allowed.has(apvIdentity(row.branch))),...(scoped.campaigns||[])]};});const newPeriods=scopedNext.filter(record=>!bdcRecords.some(existing=>existing.period===record.period));await persistBdcRecords([...merged,...newPeriods].sort((a,b)=>a.period.localeCompare(b.period)));}} showToast={showToast} canCapture={canCapture} />
        )}
        {view === 'industria' && allowedViews.includes('industria') && (
          <IndustryModuleView data={industryData} persistData={persistIndustryData} amdaData={amdaData} persistAmdaData={persistAmdaData} showToast={showToast}
            dealerRecords={homologatedRecords.filter(record=>sessionAllowedBranchNames(session,branchCatalog).some(name=>apvIdentity(name)===apvIdentity(record.sucursal)))}
            branchCatalog={branchCatalog.filter(branch=>sessionAllowedBranchNames(session,branchCatalog).some(name=>apvIdentity(name)===apvIdentity(branch.name)))}
            canImport={session.role === 'admin' || session.role === 'capturista'} />
        )}
        {view === 'geointeligencia' && allowedViews.includes('geointeligencia') && (
          <GeoIntelligenceView data={geoData} persistData={persistGeoData} showToast={showToast}
            canImport={session.role === 'admin' || session.role === 'capturista'}
            allowedBranches={sessionAllowedBranchNames(session,branchCatalog)} />
        )}
        {view === 'catalogos' && allowedViews.includes('catalogos') && (
          <CatalogosView teams={teams} branches={branchCatalog} persistBranches={persistBranchCatalog} persistTeams={persistTeams} showToast={showToast} />
        )}
        {view === 'admin' && canManageUsers && (
          <AdminUsersView users={users} persistUsers={persistUsers} showToast={showToast}
            teams={teams} branches={branchCatalog} session={session} />
        )}
      </main>
      {toast && (
        <div className={`toast toast-${toast.type}`}>
          {toast.type === 'ok' ? <Check size={16} /> : <AlertTriangle size={16} />}
          {toast.msg}
        </div>
      )}
    </div>
  );
}


/* ============================================================
   BARRA ÚNICA DE FILTROS COMERCIALES
   ============================================================ */
function StickyFilterController() {
  useEffect(()=>{
    const selector='.commercial-filter-shell,.industry-toolbar,.bdc-executive-filters,.bdc-campaign-filters,.bdc-section-capturaapv .bdc-capture-stack>section:first-child>.bdc-panel-head';
    const managed=new Map();
    let frame=0;
    const topOffset=()=>window.innerWidth<=900?0:(document.querySelector('.topbar')?.offsetHeight||96);
    const release=(element,state)=>{
      element.classList.remove('filter-docked');
      element.style.removeProperty('--dock-left');
      element.style.removeProperty('--dock-width');
      element.style.removeProperty('--dock-top');
      state.placeholder?.remove();
      managed.delete(element);
    };
    const sync=()=>{
      frame=0;
      document.querySelectorAll(selector).forEach(element=>{
        if(!managed.has(element))managed.set(element,{placeholder:null});
      });
      [...managed].forEach(([element,state])=>{
        if(!element.isConnected){release(element,state);return;}
        const offset=topOffset();
        const anchor=state.placeholder||element;
        const rect=anchor.getBoundingClientRect();
        const shouldDock=rect.top<=offset;
        if(shouldDock&&!state.placeholder){
          const placeholder=document.createElement('div');
          placeholder.className='sticky-filter-placeholder';
          placeholder.style.height=`${element.offsetHeight}px`;
          placeholder.style.width='100%';
          element.parentNode?.insertBefore(placeholder,element);
          state.placeholder=placeholder;
          const dockRect=placeholder.getBoundingClientRect();
          element.style.setProperty('--dock-left',`${dockRect.left}px`);
          element.style.setProperty('--dock-width',`${dockRect.width}px`);
          element.style.setProperty('--dock-top',`${offset}px`);
          element.classList.add('filter-docked');
        }else if(!shouldDock&&state.placeholder){
          release(element,state);
        }else if(state.placeholder){
          const dockRect=state.placeholder.getBoundingClientRect();
          state.placeholder.style.height=`${element.offsetHeight}px`;
          element.style.setProperty('--dock-left',`${dockRect.left}px`);
          element.style.setProperty('--dock-width',`${dockRect.width}px`);
          element.style.setProperty('--dock-top',`${offset}px`);
        }
      });
    };
    const schedule=()=>{if(!frame)frame=requestAnimationFrame(sync);};
    const observer=new MutationObserver(schedule);
    observer.observe(document.body,{childList:true,subtree:true});
    window.addEventListener('scroll',schedule,{passive:true});
    window.addEventListener('resize',schedule,{passive:true});
    schedule();
    return ()=>{
      observer.disconnect();
      window.removeEventListener('scroll',schedule);
      window.removeEventListener('resize',schedule);
      if(frame)cancelAnimationFrame(frame);
      [...managed].forEach(([element,state])=>release(element,state));
    };
  },[]);
  return null;
}

function CommercialFilterBar({ allowedSucursales, sucursal, setSucursal, branchScope, setBranchScope,
  months, years, selectedMonth, setSelectedMonth, managers, manager, setManager, vendors, vendor, setVendor,
  periodMode, setPeriodMode, brand, setBrand, branchType, setBranchType }) {
  const branchValue = branchScope === 'todas' ? 'todas' : sucursal;
  return <div className="commercial-filter-shell"><div className="commercial-filter-bar" style={{gridTemplateColumns:'repeat(8,minmax(105px,1fr)) auto'}}>
    <label><span>Marca</span><select value={brand} onChange={e=>{setBrand(e.target.value);setBranchScope('todas');setManager('todos');setVendor('todos');}}><option value="todas">Todas</option><option value="CHEVROLET">Chevrolet</option><option value="CHS">CHS</option></select></label>
    <label><span>Tipo</span><select value={branchType} onChange={e=>{setBranchType(e.target.value);setBranchScope('todas');setManager('todos');setVendor('todos');}}><option value="NUEVOS">Nuevos</option><option value="SEMINUEVOS">Seminuevos</option></select></label>
    <label><span>Sucursal</span><select value={branchValue} onChange={e => {
      if (e.target.value === 'todas') setBranchScope('todas');
      else { setSucursal(e.target.value); setBranchScope('sucursal'); }
      setManager('todos'); setVendor('todos');
    }}>{allowedSucursales.length > 1 && <option value="todas">Todas las sucursales</option>}{allowedSucursales.map(branch => <option key={branch} value={branch}>{sucursalLabel(branch)}</option>)}</select></label>
    <label><span>Año</span><select value={selectedMonth?.slice(0,4) || ''} onChange={e => setSelectedMonth(`${e.target.value}-${selectedMonth?.slice(5)||'01'}`)}>{years.map(year => <option key={year} value={year}>{year}</option>)}</select></label>
    <label><span>Mes</span><select value={selectedMonth || ''} onChange={e => setSelectedMonth(e.target.value)}>{months.map(month => <option key={month} value={month}>{monthLabel(month).replace(/\s+\d{4}$/,'')}</option>)}</select></label>
    <label><span>Gerente</span><select value={manager} onChange={e => { setManager(e.target.value); setVendor('todos'); }}><option value="todos">Todos los gerentes</option>{managers.map(name => <option key={name} value={name}>{name}</option>)}</select></label>
    <label><span>APV</span><select value={vendor} onChange={e => setVendor(e.target.value)}><option value="todos">Todos los APV</option>{vendors.map(name => <option key={name} value={name}>{name}</option>)}</select></label>
    <div className="commercial-period-filter"><span>Periodo</span><div className="scope-toggle"><button className={periodMode === 'mes' ? 'active' : ''} onClick={() => setPeriodMode('mes')}>Mensual</button><button className={periodMode === 'acumulado' ? 'active' : ''} onClick={() => setPeriodMode('acumulado')}>Acumulado</button></div></div>
  </div></div>;
}

