function TopBar({ view, setView, sucursal, setSucursal, allowedSucursales, allowedViews,
                  session, onLogout, onImportClick, canCapture }) {
  const backupInputRef = useRef(null);
  const ALL_ITEMS = [
    { key: 'dashboard',    label: 'Resumen Ejecutivo', icon: LayoutDashboard },
    { key: 'comparativos', label: 'Pulso Comercial',   icon: BarChart3 },
    { key: 'resumen',      label: 'Informe con IA',     icon: FileBarChart2 },
    { key: 'bdc',          label: 'BDC',                icon: Database },
    { key: 'industria',    label: 'Industria',          icon: TrendingUp },
    { key: 'geointeligencia', label: 'Geointeligencia', icon: MapPin },
    { key: 'capture',      label: 'Captura',           icon: Plus },
    { key: 'history',      label: 'Histórico',         icon: History },
    { key: 'metas',        label: 'Metas',             icon: Target },
    { key: 'catalogos',    label: 'Catálogos',         icon: Layers3 },
    { key: 'admin',        label: 'Usuarios',          icon: Shield },
  ];
  const items = ALL_ITEMS.filter(it => allowedViews.includes(it.key));
  const roleLabel = session?.profileName || ROLES[session?.role]?.label || '';
  return (
    <header className="topbar">
      <div className="topbar-row1">
        <div className="brand">
          <img src={LOGO_CR3} alt="Grupo CR3" className="brand-logo-cr3" />
          <div className="brand-logos-marcas">
            <img src={LOGO_MARCAS} alt="Chevrolet Toro · Buick · GMC · Cadillac" className="brand-logo-marcas" />
          </div>
        </div>
        <div className="sucursal-select-wrap">
          <Building2 size={14} />
          <select value={sucursal} onChange={e => setSucursal(e.target.value)} className="sucursal-select"
            disabled={allowedSucursales.length <= 1}>
            {allowedSucursales.map(s => <option key={s} value={s}>{sucursalLabel(s)}</option>)}
          </select>
        </div>
        {canCapture && (
          <div className="import-actions">
            <a className="template-download-btn" href="/Plantilla_Importacion_Historica_Funnel_KPI.xlsx" download>
              <Download size={15} /> Descargar plantilla
            </a>
            <button className="import-btn" onClick={onImportClick}>
              <Upload size={15} /> Importar Excel
            </button>
            {session?.role === 'admin' && <>
              <button className="template-download-btn" onClick={exportCompleteBackup} title="Descargar registros, equipos, catálogos, metas, BDC e Industria">
                <Download size={15} /> Respaldo completo
              </button>
              <button className="template-download-btn" onClick={() => backupInputRef.current?.click()} title="Migrar un respaldo completo a esta plataforma">
                <Upload size={15} /> Migrar respaldo
              </button>
              <input
                ref={backupInputRef}
                hidden
                type="file"
                accept=".json,application/json"
                onChange={async event => {
                  const file = event.target.files?.[0];
                  event.target.value = '';
                  if (!file) return;
                  try {
                    await importCompleteBackup(file);
                    alert('Respaldo migrado correctamente. La plataforma se recargará para mostrar toda la información.');
                    window.location.reload();
                  } catch (error) {
                    alert(error?.message || 'No fue posible migrar el respaldo.');
                  }
                }}
              />
            </>}
          </div>
        )}
        <div className="session-info">
          <div className="session-user">
            <span className="session-name">{session?.name}</span>
            <span className="session-role">{roleLabel}</span>
          </div>
          <button className="logout-btn" onClick={() => window.location.reload()} title="Actualizar información compartida">
            <RefreshCw size={15} />
          </button>
          <button className="logout-btn" onClick={onLogout} title="Cerrar sesión">
            <LogOut size={15} />
          </button>
        </div>
      </div>
      <nav className="topnav">
        {items.map(it => (
          <button key={it.key} className={`nav-btn ${view === it.key ? 'active' : ''}`} onClick={() => setView(it.key)}>
            <it.icon size={15} />
            {it.label}
          </button>
        ))}
      </nav>
    </header>
  );
}


